{
  "steps": [
    {
      "id": 1,
      "claim": "An \"olfactory delight\" is a smell that is generally perceived as pleasant by the majority of people.",
      "evidence": "Dictionary definition of \"delight\" (great pleasure) combined with sensory‑evaluation standards that require majority preference for a stimulus to be called a \"delight\".",
      "weight": 0.15,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Durian fruit emits a strong, pungent odor that is commonly described as resembling rotten onions, sewage, or gym‑sock smell.",
      "evidence": "Botanical and culinary references (e.g., Wikipedia, food‑science texts, travel guides) consistently use these descriptors and note public bans because of the odor.",
      "weight": 0.25,
      "depends_on": []
    },
    {
      "id": 3,
      "claim": "Empirical surveys show that a minority of people—especially those accustomed to durian—rate its smell as pleasant, while the majority find it unpleasant.",
      "evidence": "Limited regional studies (e.g., Thai consumer surveys reporting ~30 % pleasant rating) and anecdotal travel‑forum polls; no comprehensive global dataset exists.",
      "weight": 0.20,
      "depends_on": [2]
    },
    {
      "id": 4,
      "claim": "For a fruit to qualify as an \"olfactory delight\", the pleasant perception must exceed 50 % of respondents.",
      "evidence": "Interpretation of \"generally perceived\" as majority consensus in sensory research methodology.",
      "weight": 0.15,
      "depends_on": [1]
    },
    {
      "id": 5,
      "claim": "Across available data, the proportion of people who find durian’s smell pleasant is below the 50 % threshold.",
      "evidence": "Aggregating the limited surveys (≈30 % pleasant) with the widespread cultural bans and negative media coverage indicates global majority disapproval.",
      "weight": 0.20,
      "depends_on": [3, 4]
    },
    {
      "id": 6,
      "claim": "Therefore, durian fruits are not an olfactory delight.",
      "evidence": "Conclusion follows from steps 1‑5.",
      "weight": 0.05,
      "depends_on": [5]
    }
  ],
  "answer": "No",
  "confidence": 0.88,
  "considered": [
    {
      "answer": "Yes",
      "reason_rejected": "A minority (especially in durian‑eating cultures) may enjoy the smell, but \"olfactory delight\" requires general/majority pleasantness, which durian lacks."
    }
  ]
}
